llm.raw_content:
{
  "bioavailability_prediction": "low",
  "confidence": "low",
  "revision_action": "flip",
  "supportive_card_ids": ["C23", "C30", "C37", "C35"],
  "contradictory_card_ids": ["C01", "C07", "C08", "C13", "C36", "C39"],
  "prediction_basis_card_ids": ["C23", "C30", "C37", "C35"],
  "claims": [
    {
      "claim": "Perindoprilat, the closest ACE-inhibitor active-acid comparator, had 19 ± 7% systemic availability in normal volunteers after oral perindopril, below the F ≥ 20% threshold; this normal-condition value is more transferable to the query than the cirrhotic 30 ± 6% value.",
      "card_ids": ["C23", "C08"]
    },
    {
      "claim": "L3 enalaprilat exposure records measure enalaprilat only as a metabolite after oral enalapril (prodrug), not after direct oral enalaprilat, indicating that the active acid form is not directly orally bioavailable in this structural class.",
      "card_ids": ["C30", "C37", "C35"]
    },
    {
      "claim": "Ketoprofen oral exposure supports absorption of simple acidic drugs, but its higher lipophilicity and lack of the ACE-inhibitor active-acid/prodrug pattern limit transfer to the query.",
      "card_ids": ["C36", "C39"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "changed",
      "card_ids": ["C30", "C37", "C35", "C38", "C34", "C31", "C33"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for zofenoprilat itself is available.",
    "Enalaprilat and perindoprilat values are derived after prodrug administration, not after direct oral administration of the active acid.",
    "No permeability, efflux, or first-pass metabolism data are supplied for the query.",
    "The effect of the phenylthio and free thiol groups on absorption relative to enalaprilat/perindoprilat is not directly measured.",
    "Species differences (e.g., ampicillin calf 12% vs human 29%) limit cross-species transfer."
  ],
  "decision_summary": "Flipped to low: the closest ACE-inhibitor active-acid comparator (perindoprilat) shows 19 ± 7% systemic availability in normal volunteers, and L3 enalaprilat records confirm that the active acid is only measured after prodrug administration, indicating poor direct oral bioavailability for this class; the query's very low logD and full ionization further support F < 20%. Less transferable supportive records for simple acidic drugs do not overcome this."
}

